/* Navora 3D - SPA localStorage */
const APP_KEY='navora3d_db_v1';
const LOGIN={user:'administrador',pass:'Couve5flor*'};
const MODULE_LABELS={dashboard:'Dashboard',cadastros:'Cadastros',catalogo:'Catálogo de Produtos',estoque:'Estoque',compras:'Compras',producao:'Produção',vendas:'Vendas',financeiro:'Financeiro',orcamentos:'Orçamentos',configuracoes:'Configurações'};
const nowISO=()=>new Date().toISOString();
const uid=(p='ID')=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const dateBR=v=>v?new Date(v).toLocaleDateString('pt-BR'):'-';
const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
const num=v=>Number(String(v??'').replace(',','.'))||0;
const moneyInput=v=>String(v??'').replace('.',',');
const uidCode=(prefix,seq)=>`${prefix}${String(seq).padStart(6,'0')}`;
const blankDB=()=>({meta:{createdAt:nowISO(),updatedAt:nowISO()},cadastros:{clientes:[],fornecedores:[],materiais:[],categorias:[],cores:[],impressoras:[]},produtos:[],compras:[],estoque:[],producoes:[],vendas:[],financeiro:[],orcamentos:[]});
let db=loadDB(); let currentModule='dashboard'; let dashboardCharts={}; let cadTab='clientes';
function normalizeDB(data){const base=blankDB();const out={...base,...(data||{})};out.meta={...base.meta,...(data?.meta||{})};out.cadastros={...base.cadastros,...(data?.cadastros||{})};out.cadastros.impressoras=Array.isArray(out.cadastros.impressoras)?out.cadastros.impressoras:[];out.orcamentos=Array.isArray(out.orcamentos)?out.orcamentos:[];let seq=1;out.producoes=Array.isArray(out.producoes)?out.producoes:[];out.producoes.forEach(o=>{if(!o.codigo)o.codigo=uidCode('PRD',seq++);});return out}
function loadDB(){try{return normalizeDB(JSON.parse(localStorage.getItem(APP_KEY)||'{}'))}catch{return blankDB()}}
function saveDB(){db.meta.updatedAt=nowISO();localStorage.setItem(APP_KEY,JSON.stringify(db));}
function toast(msg,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;document.getElementById('toast-container').appendChild(el);setTimeout(()=>el.remove(),2800)}
function setModule(m){currentModule=m;document.querySelectorAll('.nav-item[data-module]').forEach(b=>b.classList.toggle('active',b.dataset.module===m));document.getElementById('page-title').textContent=MODULE_LABELS[m];document.getElementById('page-kicker').textContent=m==='dashboard'?'Visão geral':'Gestão operacional';renderModule();window.scrollTo({top:0,behavior:'smooth'})}
function renderModule(){const root=document.getElementById('module-root');root.innerHTML='';if(currentModule==='dashboard')renderDashboard(root);if(currentModule==='cadastros')renderCadastros(root);if(currentModule==='catalogo')renderCatalogo(root);if(currentModule==='estoque')renderEstoque(root);if(currentModule==='compras')renderCompras(root);if(currentModule==='producao')renderProducao(root);if(currentModule==='vendas')renderVendas(root);if(currentModule==='financeiro')renderFinanceiro(root);if(currentModule==='orcamentos')renderOrcamentos(root);if(currentModule==='configuracoes')renderConfiguracoes(root)}

function renderDashboard(root){
 const sales=db.vendas;const revenue=sales.reduce((s,x)=>s+num(x.valorFinal),0);const profit=sales.reduce((s,x)=>s+(num(x.valorFinal)-estimatedCost(x.produtoId,x.qtde)),0);
 root.innerHTML=`<div class="section-head"><div><h2>Painel gerencial</h2><p>Indicadores e evolução das vendas da Navora 3D.</p></div><div class="toolbar"><button class="btn btn-secondary" id="dash-reset">Limpar filtros</button></div></div>
 <div class="filters"><label>Período início<input type="date" id="df-from"></label><label>Período fim<input type="date" id="df-to"></label><label>Cliente<select id="df-client"><option value="">Todos</option>${db.cadastros.clientes.map(c=>`<option value="${c.id}">${esc(c.nome)}</option>`).join('')}</select></label><label>Produto<select id="df-product"><option value="">Todos</option>${db.produtos.map(p=>`<option value="${p.id}">${esc(p.descricao)}</option>`).join('')}</select></label><label>Categoria<select id="df-category"><option value="">Todas</option>${db.cadastros.categorias.map(c=>`<option value="${c.id}">${esc(c.descricao)}</option>`).join('')}</select></label></div>
 <div class="cards"><div class="card metric"><div class="label">Faturamento total</div><div class="value" id="dash-revenue">${money(revenue)}</div><div class="sub">Vendas no período selecionado</div></div><div class="card metric"><div class="label">Lucro estimado</div><div class="value" id="dash-profit">${money(profit)}</div><div class="sub">Receita menos custo estimado</div></div><div class="card metric"><div class="label">Vendas realizadas</div><div class="value" id="dash-count">${sales.length}</div><div class="sub">Pedidos registrados</div></div></div>
 <div class="grid-2"><div class="card chart-card"><h3>Vendas dos últimos 30 dias</h3><div class="chart-wrap"><canvas id="sales-chart"></canvas></div></div><div class="card chart-card"><h3>Resumo por produto</h3><div class="chart-wrap"><canvas id="product-chart"></canvas></div></div></div>`;
 ['df-from','df-to','df-client','df-product','df-category'].forEach(id=>document.getElementById(id).addEventListener('change',updateDashboard));
 document.getElementById('dash-reset').onclick=()=>{['df-from','df-to','df-client','df-product','df-category'].forEach(id=>document.getElementById(id).value='');updateDashboard()};updateDashboard()
}
function filteredSales(){const from=document.getElementById('df-from')?.value,to=document.getElementById('df-to')?.value,cl=document.getElementById('df-client')?.value,pr=document.getElementById('df-product')?.value,cat=document.getElementById('df-category')?.value;return db.vendas.filter(s=>{const d=s.data?.slice(0,10),p=db.produtos.find(x=>x.id===s.produtoId);return(!from||d>=from)&&(!to||d<=to)&&(!cl||s.clienteId===cl)&&(!pr||s.produtoId===pr)&&(!cat||p?.categoriaId===cat)})}
function updateDashboard(){const sales=filteredSales();const revenue=sales.reduce((s,x)=>s+num(x.valorFinal),0);const profit=sales.reduce((s,x)=>s+(num(x.valorFinal)-estimatedCost(x.produtoId,x.qtde)),0);document.getElementById('dash-revenue').textContent=money(revenue);document.getElementById('dash-profit').textContent=money(profit);document.getElementById('dash-count').textContent=sales.length;renderCharts(sales)}
function estimatedCost(productId,qty){const p=db.produtos.find(x=>x.id===productId);if(!p)return 0;const comps=db.compras.filter(c=>c.produtoId===productId);if(comps.length)return comps.reduce((s,c)=>s+((num(c.valorTotal)/Math.max(1,num(c.qtde)))*num(qty)),0);return 0}
function renderCharts(sales){const labels=[],vals=[];for(let i=29;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toISOString().slice(0,10);labels.push(d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}));vals.push(sales.filter(s=>(s.data||'').slice(0,10)===key).reduce((a,x)=>a+num(x.valorFinal),0))}if(dashboardCharts.sales)dashboardCharts.sales.destroy();if(dashboardCharts.products)dashboardCharts.products.destroy();dashboardCharts.sales=new Chart(document.getElementById('sales-chart'),{type:'line',data:{labels,datasets:[{label:'Faturamento',data:vals,tension:.35,fill:true}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});const map={};sales.forEach(s=>map[s.produtoId]=(map[s.produtoId]||0)+num(s.valorFinal));const pNames=Object.keys(map).map(id=>db.produtos.find(p=>p.id===id)?.descricao||'Produto');dashboardCharts.products=new Chart(document.getElementById('product-chart'),{type:'doughnut',data:{labels:pNames.length?pNames:['Sem vendas'],datasets:[{data:pNames.length?Object.values(map):[1]}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}})}

const cadDefs={
 clientes:{title:'Clientes',fields:[['nome','Nome completo','text',true],['cpf','CPF/CNPJ','text',false],['telefone','Telefone','text',false],['email','E-mail','email',false],['cidade','Cidade','text',false],['observacoes','Observações','textarea',false]]},
 fornecedores:{title:'Fornecedores',fields:[['nome','Nome/Razão Social','text',true],['cpf','CPF/CNPJ','text',false],['contato','Contato','text',false],['email','E-mail','email',false],['cidade','Cidade','text',false],['observacoes','Observações','textarea',false]]},
 materiais:{title:'Materiais',fields:[['descricao','Material','text',true],['observacoes','Observações','textarea',false]]},
 categorias:{title:'Categorias',fields:[['descricao','Categoria','text',true]]},
 cores:{title:'Cores',fields:[['descricao','Cor','text',true]]},
 impressoras:{title:'Impressoras',fields:[['nome','Nome','text',true],['modelo','Modelo','text',false],['marca','Marca','text',false],['potencia','Potência (W)','number',false],['vidaUtil','Vida útil (h)','number',false],['valor','Valor (R$)','number',false]]}
};
function renderCadastros(root){const def=cadDefs[cadTab];root.innerHTML=`<div class="section-head"><div><h2>Cadastros centralizados</h2><p>Cadastre, consulte, altere e remova os dados mestres da operação.</p></div><button class="btn btn-primary" id="add-cadastro">+ Novo cadastro</button></div><div class="tabs">${Object.entries(cadDefs).map(([k,v])=>`<button class="tab ${k===cadTab?'active':''}" data-tab="${k}">${v.title}</button>`).join('')}</div><div class="card panel"><div class="table-wrap" id="cad-table"></div></div>`;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{cadTab=b.dataset.tab;renderCadastros(root)});document.getElementById('add-cadastro').onclick=()=>openCadModal(cadTab);renderCadTable()}
function formatCadValue(type,key,val){if(type==='impressoras'&&['potencia','vidaUtil','valor'].includes(key))return key==='valor'?money(val):num(val).toFixed(2);return esc(val)||'-'}
function renderCadTable(){const def=cadDefs[cadTab],rows=db.cadastros[cadTab]||[];const head=def.fields.map(f=>`<th>${f[1]}</th>`).join('');document.getElementById('cad-table').innerHTML=rows.length?`<table class="data-table"><thead><tr>${head}<th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr>${def.fields.map(f=>`<td>${formatCadValue(cadTab,f[0],r[f[0]])}</td>`).join('')}<td><div class="actions"><button class="small-btn" onclick="openCadModal('${cadTab}','${r.id}')">Editar</button><button class="small-btn" onclick="deleteCad('${cadTab}','${r.id}')">Excluir</button></div></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Nenhum registro</strong>Comece adicionando um novo ${def.title.toLowerCase().slice(0,-1)}.</div>`}
function openCadModal(type,id){const def=cadDefs[type],r=(db.cadastros[type]||[]).find(x=>x.id===id)||{};openModal(def.title,id?'Editar cadastro':'Novo cadastro',`<div class="form-grid">${def.fields.map(f=>{const[key,label,typ,required]=f;const step=typ==='number'?(key==='valor'?'0.01':'0.01'):'';const value=key==='valor'?moneyInput(r[key]):esc(r[key]||'');return `<label class="${typ==='textarea'?'col-12':'col-6'}">${label}${required?' *':''}${typ==='textarea'?`<textarea id="f_${key}">${value}</textarea>`:`<input id="f_${key}" type="${typ}" value="${value}" ${required?'required':''} ${step?`step="${step}"`:''}>`}</label>`}).join('')}</div>`,()=>{const obj={id:r.id||uid(type.slice(0,3).toUpperCase())};for(const[key,label,typ,required]of def.fields){const el=document.getElementById('f_'+key);const v=typ==='number'?num(el.value):el.value.trim();if(required&&(!String(v).trim()||v===0&&key==='valor')){toast(`Preencha ${label}.`,'error');return}obj[key]=v}if(id)Object.assign(r,obj);else db.cadastros[type].push(obj);saveDB();closeModal();renderCadastros(document.getElementById('module-root'));toast('Cadastro salvo.')})}
window.openCadModal=openCadModal;window.deleteCad=(type,id)=>{if(!confirm('Excluir este cadastro?'))return;db.cadastros[type]=db.cadastros[type].filter(x=>x.id!==id);saveDB();renderCadastros(document.getElementById('module-root'));toast('Cadastro excluído.','error')};

function productColors(p){const ids=Array.isArray(p.corIds)?p.corIds:(p.corId?[p.corId]:[]);return ids.map(id=>db.cadastros.cores.find(c=>c.id===id)?.descricao).filter(Boolean)}
function renderCatalogo(root){const fq=(window.catalogFilters||={descricao:'',categoria:'',cor:'',dimensao:''});const prods=db.produtos.filter(p=>{const cs=productColors(p).join(' ').toLowerCase();return(!fq.descricao||p.descricao.toLowerCase().includes(fq.descricao.toLowerCase()))&&(!fq.categoria||p.categoriaId===fq.categoria)&&(!fq.cor||((p.corIds||[p.corId]).includes(fq.cor)))&&(!fq.dimensao||String(p.dimensoes||'').toLowerCase().includes(fq.dimensao.toLowerCase()))});root.innerHTML=`<div class="section-head"><div><h2>Catálogo de Produtos</h2><p>Produtos vendidos, parâmetros de produção e últimas vendas.</p></div><button class="btn btn-primary" id="add-prod">+ Novo produto</button></div><div class="filters"><label>Descrição<input id="cat_desc" placeholder="Pesquisar" value="${esc(fq.descricao)}"></label><label>Categoria<select id="cat_cat"><option value="">Todas</option>${db.cadastros.categorias.map(x=>`<option value="${x.id}" ${fq.categoria===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label>Cor<select id="cat_cor"><option value="">Todas</option>${db.cadastros.cores.map(x=>`<option value="${x.id}" ${fq.cor===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label>Dimensão<input id="cat_dim" placeholder="Ex.: 20,00" value="${esc(fq.dimensao)}"></label></div><div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Categoria</th><th>Material</th><th>Cor</th><th>Dimensões</th><th>Tempo</th><th>Preço sugerido</th><th>Ações</th></tr></thead><tbody>${prods.length?prods.map(p=>{const c=db.cadastros.categorias.find(x=>x.id===p.categoriaId)?.descricao||'-',m=db.cadastros.materiais.find(x=>x.id===p.materialId)?.descricao||'-',co=productColors(p).join(', ')||'-';return `<tr><td><strong>${esc(p.descricao)}</strong></td><td>${esc(c)}</td><td>${esc(m)}</td><td>${esc(co)}</td><td>${esc(p.dimensoes)}</td><td>${p.horas||0}h ${p.minutos||0}m</td><td>${money(p.preco)}</td><td><div class="actions"><button class="small-btn" onclick="openProductModal('${p.id}')">Editar</button><button class="small-btn" onclick="showLastSales('${p.id}')">Últimas vendas</button><button class="small-btn" onclick="deleteProduct('${p.id}')">Excluir</button></div></td></tr>`}).join(''):`<tr><td colspan="8"><div class="empty-state">Nenhum produto encontrado.</div></td></tr>`}</tbody></table></div></div>`;document.getElementById('add-prod').onclick=()=>openProductModal();['cat_desc','cat_cat','cat_cor','cat_dim'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{window.catalogFilters={descricao:document.getElementById('cat_desc').value,categoria:document.getElementById('cat_cat').value,cor:document.getElementById('cat_cor').value,dimensao:document.getElementById('cat_dim').value};renderCatalogo(document.getElementById('module-root'))}))}
function productForm(r={}){const selected=new Set(Array.isArray(r.corIds)?r.corIds:(r.corId?[r.corId]:[]));return `<div class="form-grid"><label class="col-6">Descrição *<input id="p_desc" value="${esc(r.descricao||'')}" required></label><label class="col-6">Categoria *<select id="p_cat" required><option value="">Selecione</option>${db.cadastros.categorias.map(x=>`<option value="${x.id}" ${r.categoriaId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label class="col-6">Material *<select id="p_mat" required><option value="">Selecione</option>${db.cadastros.materiais.map(x=>`<option value="${x.id}" ${r.materialId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><div class="col-6"><label>Cor *<select id="p_cor" multiple size="4" required>${db.cadastros.cores.map(x=>`<option value="${x.id}" ${selected.has(x.id)?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><div class="inline-note" style="margin-top:7px">Use Ctrl/Cmd para selecionar mais de uma cor.</div></div><label class="col-6">Dimensões *<input id="p_dim" placeholder="20,00 x 10,50 x 5,00" value="${esc(r.dimensoes||'')}" required></label><label class="col-2">Horas *<input id="p_h" type="number" min="0" value="${r.horas||0}" required></label><label class="col-2">Minutos *<input id="p_m" type="number" min="0" max="59" value="${r.minutos||0}" required></label><label class="col-2">Preço sugerido (R$) *<input id="p_price" inputmode="decimal" value="${moneyInput(r.preco)}" required></label><label class="col-12">Observações<textarea id="p_obs">${esc(r.observacoes||'')}</textarea></label><div class="col-12 inline-note">Dimensões são armazenadas como texto para permitir formatos como “20,00 x 10,00 x 5,00”.</div></div>`}
window.openProductModal=(id)=>{const r=db.produtos.find(x=>x.id===id)||{};openModal('Catálogo de Produtos',id?'Editar produto':'Novo produto',productForm(r),()=>{const required=['p_desc','p_cat','p_mat','p_dim','p_h','p_m','p_price'];if(required.some(x=>!document.getElementById(x).value.trim())){toast('Preencha os campos obrigatórios.','error');return}const colors=[...document.getElementById('p_cor').selectedOptions].map(o=>o.value);if(!colors.length){toast('Selecione ao menos uma cor.','error');return}const obj={id:r.id||uid('PROD'),descricao:document.getElementById('p_desc').value.trim(),categoriaId:document.getElementById('p_cat').value,materialId:document.getElementById('p_mat').value,corIds:colors,corId:colors[0],dimensoes:document.getElementById('p_dim').value.trim(),horas:num(document.getElementById('p_h').value),minutos:Math.floor(num(document.getElementById('p_m').value)),preco:num(document.getElementById('p_price').value),observacoes:document.getElementById('p_obs').value.trim()};if(id)Object.assign(r,obj);else db.produtos.push(obj);saveDB();closeModal();renderCatalogo(document.getElementById('module-root'));toast('Produto salvo.')})};window.deleteProduct=id=>{if(!confirm('Excluir produto?'))return;db.produtos=db.produtos.filter(x=>x.id!==id);saveDB();renderCatalogo(document.getElementById('module-root'));toast('Produto excluído.','error')};
function showLastSales(id){const p=db.produtos.find(x=>x.id===id),sales=db.vendas.filter(s=>s.produtoId===id).sort((a,b)=>new Date(b.data)-new Date(a.data)).slice(0,3);openModal('Últimas vendas',p?.descricao||'Produto',sales.length?`<table class="data-table"><thead><tr><th>Data</th><th>Cliente</th><th>Dimensões</th><th>Valor</th><th>Observações</th></tr></thead><tbody>${sales.map(s=>`<tr><td>${dateBR(s.data)}</td><td>${esc(db.cadastros.clientes.find(c=>c.id===s.clienteId)?.nome||'-')}</td><td>${esc(p?.dimensoes||'-')}</td><td>${money(s.valorFinal)}</td><td>${esc(s.observacoes||'-')}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Sem vendas</strong>Ainda não existem vendas para este produto.</div>`,null)}

function renderEstoque(root){root.innerHTML=`<div class="section-head"><div><h2>Estoque</h2><p>Consulte apenas o produto/material necessário e faça ajustes de estoque.</p></div></div><div class="filters"><label>Produto<input id="s_prod" placeholder="Pesquisar"></label><label>Fornecedor<select id="s_forn"><option value="">Todos</option>${db.cadastros.fornecedores.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Cor<select id="s_cor"><option value="">Todas</option>${db.cadastros.cores.map(x=>`<option value="${x.id}">${esc(x.descricao)}</option>`).join('')}</select></label><label>Tipo<select id="s_tipo"><option value="">Todos</option><option>Filamento</option><option>Componente</option><option>Outro</option><option>Outros</option></select></label><label>Material<select id="s_mat"><option value="">Todos</option>${db.cadastros.materiais.map(x=>`<option value="${x.id}">${esc(x.descricao)}</option>`).join('')}</select></label></div><div class="card panel"><div id="stock-result"></div></div>`;['s_prod','s_forn','s_cor','s_tipo','s_mat'].forEach(id=>document.getElementById(id).addEventListener('input',renderStockTable));renderStockTable()}
function renderStockTable(){const prod=document.getElementById('s_prod').value.toLowerCase(),forn=document.getElementById('s_forn').value,cor=document.getElementById('s_cor').value,tipo=document.getElementById('s_tipo').value,mat=document.getElementById('s_mat').value;const rows=db.estoque.filter(x=>(!prod||x.descricao.toLowerCase().includes(prod))&&(!forn||x.fornecedorId===forn)&&(!cor||x.corId===cor)&&(!tipo||x.tipo===tipo)&&(!mat||x.materialId===mat));document.getElementById('stock-result').innerHTML=rows.length?`<table class="data-table"><thead><tr><th>Produto</th><th>Fornecedor</th><th>Cor</th><th>Tipo</th><th>Material</th><th>Qtde estoque</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.descricao)}</td><td>${esc(db.cadastros.fornecedores.find(f=>f.id===x.fornecedorId)?.nome||'-')}</td><td>${esc(db.cadastros.cores.find(c=>c.id===x.corId)?.descricao||x.cor||'-')}</td><td>${esc(x.tipo)}</td><td>${esc(db.cadastros.materiais.find(m=>m.id===x.materialId)?.descricao||x.material||'-')}</td><td><strong>${num(x.qtde).toFixed(2)}</strong></td><td><span class="status-pill ${num(x.qtde)>0?'status-ok':'status-empty'}">${num(x.qtde)>0?'Disponível':'Sem estoque'}</span></td><td><button class="small-btn" onclick="adjustStock('${x.id}')">Ajustar</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Nenhum resultado</strong>Pesquise um produto ou material para visualizar o estoque.</div>`}
window.adjustStock=id=>{const x=db.estoque.find(e=>e.id===id);openModal('Ajuste de estoque',x?.descricao||'',`<div class="form-grid"><label class="col-6">Quantidade atual<input value="${num(x.qtde).toFixed(2)}" disabled></label><label class="col-6">Novo saldo<input id="stk_new" inputmode="decimal" value="${num(x.qtde).toFixed(2)}"></label><label class="col-12">Motivo<textarea id="stk_note" placeholder="Ex.: perda, correção, inventário..."></textarea></label></div>`,()=>{x.qtde=num(document.getElementById('stk_new').value);x.updatedAt=nowISO();saveDB();closeModal();renderEstoque(document.getElementById('module-root'));toast('Estoque ajustado.')})}

function renderCompras(root){root.innerHTML=`<div class="section-head"><div><h2>Compras</h2><p>Registre matérias-primas, componentes, embalagens e demais insumos.</p></div><button class="btn btn-primary" id="add-compra">+ Nova compra</button></div><div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Tipo</th><th>Fornecedor</th><th>Qtde (g)</th><th>Cor</th><th>Alerta mín.</th><th>Valor</th><th>Frete</th><th>Outros</th><th>Total</th><th>Ações</th></tr></thead><tbody>${db.compras.length?db.compras.map(x=>`<tr><td>${esc(x.descricao)}</td><td>${esc(x.tipo)}</td><td>${esc(db.cadastros.fornecedores.find(f=>f.id===x.fornecedorId)?.nome||'-')}</td><td>${num(x.qtde).toFixed(2)}</td><td>${esc(db.cadastros.cores.find(c=>c.id===x.corId)?.descricao||'-')}</td><td>${num(x.alerta).toFixed(2)}</td><td>${money(x.valor)}</td><td>${money(x.frete)}</td><td>${money(x.outros)}</td><td><strong>${money(x.valorTotal)}</strong></td><td><div class="actions"><button class="small-btn" onclick="openCompraModal('${x.id}')">Editar</button><button class="small-btn" onclick="deleteCompra('${x.id}')">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="11"><div class="empty-state">Nenhuma compra cadastrada.</div></td></tr>`}</tbody></table></div></div>`;document.getElementById('add-compra').onclick=()=>openCompraModal()}
function compraForm(r={}){return `<div class="form-grid"><label class="col-6">Descrição *<input id="c_desc" value="${esc(r.descricao||'')}" required></label><label class="col-3">Tipo *<select id="c_tipo" required><option value="">Selecione</option>${['Filamento','Componente','Outros'].map(v=>`<option ${r.tipo===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="col-3">Fornecedor *<select id="c_forn" required><option value="">Selecione</option>${db.cadastros.fornecedores.map(x=>`<option value="${x.id}" ${r.fornecedorId===x.id?'selected':''}>${esc(x.nome)}</option>`).join('')}</select></label><label class="col-4">Qtde (g) *<input id="c_q" inputmode="decimal" value="${r.qtde??''}" required></label><label class="col-4">Cor *<select id="c_cor" required><option value="">Selecione</option>${db.cadastros.cores.map(x=>`<option value="${x.id}" ${r.corId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label class="col-4">Material<select id="c_mat"><option value="">Selecione</option>${db.cadastros.materiais.map(x=>`<option value="${x.id}" ${r.materialId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label class="col-4">Alerta estoque mínimo<input id="c_alerta" inputmode="decimal" value="${r.alerta??''}"></label><label class="col-4">Valor (R$)<input id="c_valor" inputmode="decimal" value="${moneyInput(r.valor)}"></label><label class="col-4">Frete (R$)<input id="c_frete" inputmode="decimal" value="${moneyInput(r.frete)}"></label><label class="col-4">Outros (R$)<input id="c_outros" inputmode="decimal" value="${moneyInput(r.outros)}"></label><div class="col-12 inline-note">Valor total calculado = valor da compra + frete + outros.</div></div>`}
window.openCompraModal=id=>{const r=db.compras.find(x=>x.id===id)||{};openModal('Compras',id?'Editar compra':'Nova compra',compraForm(r),()=>{if(!document.getElementById('c_desc').value.trim()||!document.getElementById('c_tipo').value||!document.getElementById('c_forn').value||!document.getElementById('c_q').value||!document.getElementById('c_cor').value){toast('Preencha os campos obrigatórios.','error');return}if(id&&r._stockApplied){removeCompraFromStock(r)}const obj={id:r.id||uid('COMP'),descricao:document.getElementById('c_desc').value.trim(),tipo:document.getElementById('c_tipo').value,fornecedorId:document.getElementById('c_forn').value,qtde:num(document.getElementById('c_q').value),corId:document.getElementById('c_cor').value,materialId:document.getElementById('c_mat').value,alerta:num(document.getElementById('c_alerta').value),valor:num(document.getElementById('c_valor').value),frete:num(document.getElementById('c_frete').value),outros:num(document.getElementById('c_outros').value),_stockApplied:false};obj.valorTotal=obj.valor+obj.frete+obj.outros;if(id)Object.assign(r,obj);else db.compras.push(obj);syncStockFromCompra(id?r:obj);saveDB();closeModal();renderCompras(document.getElementById('module-root'));toast('Compra salva e estoque atualizado.')})};
function syncStockFromCompra(c){let x=db.estoque.find(e=>e.descricao.toLowerCase()===c.descricao.toLowerCase()&&e.fornecedorId===c.fornecedorId&&e.tipo===c.tipo&&e.corId===c.corId&&e.materialId===c.materialId);if(!x){x={id:uid('EST'),descricao:c.descricao,tipo:c.tipo,fornecedorId:c.fornecedorId,corId:c.corId,materialId:c.materialId,qtde:0,alerta:c.alerta};db.estoque.push(x)}x.alerta=c.alerta;if(!c._stockApplied){x.qtde+=c.qtde;c._stockApplied=true}}
function removeCompraFromStock(c){const x=db.estoque.find(e=>e.descricao.toLowerCase()===c.descricao.toLowerCase()&&e.fornecedorId===c.fornecedorId&&e.tipo===c.tipo&&e.corId===c.corId&&e.materialId===c.materialId);if(x){x.qtde=Math.max(0,num(x.qtde)-num(c.qtde));if(num(x.qtde)<=0)db.estoque=db.estoque.filter(e=>e.id!==x.id)}}
window.deleteCompra=id=>{if(!confirm('Excluir esta compra? O estoque correspondente também será removido.'))return;const c=db.compras.find(x=>x.id===id);if(c&&c._stockApplied)removeCompraFromStock(c);db.compras=db.compras.filter(x=>x.id!==id);saveDB();renderCompras(document.getElementById('module-root'));toast('Compra e estoque correspondente excluídos.','error')};

function nextProductionNumber(){const nums=db.producoes.map(x=>parseInt(String(x.codigo||x.id||'').replace(/^PRD/i,''),10)).filter(Number.isFinite);return Math.max(0,...nums)+1}
function productionCode(o){if(o.codigo)return o.codigo;const n=parseInt(String(o.id||'').replace(/^OP-?/i,''),36);return isNaN(n)?`PRD${String(db.producoes.indexOf(o)+1).padStart(6,'0')}`:`PRD${String((Math.abs(n)%999999)+1).padStart(6,'0')}`}
function orderMaterialSummary(o){const mats=o.materiais||[];if(!mats.length)return '-';const grouped={};mats.forEach(m=>{const c=db.cadastros.cores.find(x=>x.id===m.corId)?.descricao||m.cor||m.descricao||'-';grouped[c]=(grouped[c]||0)+num(m.gramas)});const sorted=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);return sorted.length>1?`${sorted[0][0]}, ...`:sorted[0][0]}
function productStockInfo(productId){const p=db.produtos.find(x=>x.id===productId);if(!p)return{qty:0,color:'empty'};const qty=num(p.qtde);return{qty,color:qty>0?'ok':'empty'} }
function renderProducao(root){root.innerHTML=`<div class="section-head"><div><h2>Produção</h2><p>Ordens de produção, consumo de materiais e entrada de produtos acabados.</p></div><button class="btn btn-primary" id="add-op">+ Nova ordem</button></div><div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Produto</th><th>Cor</th><th>Qtde</th><th>Material</th><th>Status</th><th>Venda</th><th>Observações</th><th>Ações</th></tr></thead><tbody>${db.producoes.length?db.producoes.map(o=>`<tr><td><strong>${esc(productionCode(o))}</strong></td><td>${esc(db.produtos.find(p=>p.id===o.produtoId)?.descricao||'-')}</td><td>${esc(db.cadastros.cores.find(c=>c.id===o.corId)?.descricao||'-')}</td><td>${num(o.qtde)}</td><td>${esc(orderMaterialSummary(o))}</td><td>${productionStatus(o.status)}</td><td>${esc(o.vendaId||'-')}</td><td>${esc(o.observacoes||'-')}</td><td><div class="actions"><button class="small-btn" onclick="openOPModal('${o.id}')">Editar</button><button class="small-btn" onclick="generateSale('${o.id}')">Gerar venda</button><button class="small-btn" onclick="deleteOP('${o.id}')">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="9"><div class="empty-state">Nenhuma ordem de produção.</div></td></tr>`}</tbody></table></div></div>`;document.getElementById('add-op').onclick=()=>openOPModal()}
const productionStatus=s=>`<span class="status-pill ${s==='Finalizado'?'status-ok':s==='Em produção'?'status-production':'status-wait'}">${esc(s)}</span>`;
function materialOptionsForProduct(r={}){const current=new Set((r.materiais||[]).map(m=>m.estoqueId));return db.estoque.filter(s=>num(s.qtde)>0||current.has(s.id))}
function opMaterialRows(r={}){const mats=r.materiais||[],available=materialOptionsForProduct(r);if(!available.length)return '<div class="inline-note">Nenhum material com estoque positivo.</div>';return available.map(s=>{const sel=mats.find(m=>m.estoqueId===s.id);const color=db.cadastros.cores.find(c=>c.id===s.corId)?.descricao||'-';return `<div class="material-row"><div><strong>${esc(s.descricao)}</strong><div class="muted" style="margin-top:4px;font-size:11px">Estoque: ${num(s.qtde).toFixed(2)} g</div></div><div><label>Cor<div class="material-color">${esc(color)}</div></label></div><div><label>Gramas<input class="op-g" data-id="${s.id}" value="${sel?.gramas??''}" inputmode="decimal"></label></div><div class="material-action"><button type="button" class="small-btn ${sel?'btn-primary':''} op-use" data-id="${s.id}">${sel?'Adicionado':'Adicionar'}</button></div></div>`}).join('')}
function opForm(r={}){const stock=productStockInfo(r.produtoId);return `<div class="form-grid"><label class="col-7">Produto *<select id="o_prod" required><option value="">Selecione</option>${db.produtos.map(x=>`<option value="${x.id}" ${r.produtoId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label class="col-2">Estoque<div id="o_stock" class="stock-indicator ${stock.color}">${stock.qty}</div></label><label class="col-3">Qtde *<input id="o_q" type="number" min="1" value="${r.qtde||1}" required></label><label class="col-6">Cor *<select id="o_cor" required><option value="">Selecione</option>${db.cadastros.cores.map(x=>`<option value="${x.id}" ${r.corId===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><div class="col-12"><div class="section-head compact"><div><strong>Materiais / Filamentos</strong><div class="muted">Selecione os materiais disponíveis, informe as gramas e adicione vários registros.</div></div><button type="button" class="btn btn-secondary" id="op-refresh-materials">Atualizar materiais</button></div><div class="production-materials" id="op-materials">${opMaterialRows(r)}</div></div><label class="col-3">Status *<select id="o_status" required>${['Aguardando','Em produção','Finalizado'].map(v=>`<option ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="col-9">Observações<textarea id="o_obs">${esc(r.observacoes||'')}</textarea></label></div>`}
window.openOPModal=(id,draft)=>{const r=id?db.producoes.find(x=>x.id===id)||{}:(draft||{});openModal('Produção',id?'Editar ordem de produção':'Nova ordem de produção',opForm(r),()=>{const prod=document.getElementById('o_prod').value,cor=document.getElementById('o_cor').value,q=num(document.getElementById('o_q').value),status=document.getElementById('o_status').value;if(!prod||!cor||q<=0||!status){toast('Preencha os campos obrigatórios.','error');return}const mats=[...document.querySelectorAll('.material-row')].filter(row=>row.querySelector('.op-use')?.classList.contains('btn-primary')).map(row=>{const use=row.querySelector('.op-use'),stock=db.estoque.find(x=>x.id===use.dataset.id),g=row.querySelector('.op-g');return{estoqueId:stock.id,descricao:stock.descricao,gramas:num(g.value),corId:stock.corId}});if(!mats.length){toast('Adicione ao menos um material.','error');return}if(mats.some(m=>m.gramas<=0)){toast('Informe as gramas para cada material selecionado.','error');return}if(mats.some(m=>num(m.gramas)>num(db.estoque.find(s=>s.id===m.estoqueId)?.qtde))){toast('A quantidade de gramas não pode ser maior que o estoque disponível.','error');return}const obj={id:r.id||uid('OP'),codigo:r.codigo||uidCode('PRD',nextProductionNumber()),produtoId:prod,corId:cor,qtde:q,materiais:mats,status,observacoes:document.getElementById('o_obs').value.trim(),finishedApplied:r.finishedApplied||false,vendaId:r.vendaId||null,orcamentoId:r.orcamentoId||null};if(id){if(r.status==='Finalizado'&&status!=='Finalizado'&&r.finishedApplied)reverseFinishedProduction(r);Object.assign(r,obj);if(r.status==='Finalizado'&&!r.finishedApplied)applyFinishedProduction(r)}else{db.producoes.push(obj);if(obj.status==='Finalizado')applyFinishedProduction(obj)}saveDB();closeModal();renderProducao(document.getElementById('module-root'));toast('Ordem de produção salva.')});setTimeout(()=>{document.getElementById('o_prod')?.addEventListener('change',()=>{const stock=productStockInfo(document.getElementById('o_prod').value);document.getElementById('o_stock').className=`stock-indicator ${stock.color}`;document.getElementById('o_stock').textContent=stock.qty});document.getElementById('op-refresh-materials')?.addEventListener('click',()=>{const current={materiais:[...document.querySelectorAll('.material-row')].filter(row=>row.querySelector('.op-use')?.classList.contains('btn-primary')).map(row=>{const use=row.querySelector('.op-use'),g=row.querySelector('.op-g'),s=db.estoque.find(x=>x.id===use.dataset.id);return{estoqueId:s.id,gramas:num(g.value),descricao:s.descricao,corId:s.corId}})};document.getElementById('op-materials').innerHTML=opMaterialRows(current);bindOPMaterialButtons()});bindOPMaterialButtons()},0)};
function bindOPMaterialButtons(){document.querySelectorAll('.op-use').forEach(btn=>btn.addEventListener('click',()=>{btn.classList.toggle('btn-primary');btn.textContent=btn.classList.contains('btn-primary')?'Adicionado':'Adicionar';const row=btn.closest('.material-row');if(!btn.classList.contains('btn-primary'))row.querySelector('.op-g').value=''}))}
function applyFinishedProduction(o){o.materiais.forEach(m=>{const stock=db.estoque.find(x=>x.id===m.estoqueId);if(stock)stock.qtde=Math.max(0,num(stock.qtde)-num(m.gramas))});const p=db.produtos.find(x=>x.id===o.produtoId);if(p)p.qtde=num(p.qtde)+num(o.qtde);o.finishedApplied=true}
function reverseFinishedProduction(o){o.materiais.forEach(m=>{const stock=db.estoque.find(x=>x.id===m.estoqueId);if(stock)stock.qtde+=num(m.gramas)});const p=db.produtos.find(x=>x.id===o.produtoId);if(p)p.qtde=Math.max(0,num(p.qtde)-num(o.qtde));o.finishedApplied=false}
window.deleteOP=id=>{if(!confirm('Excluir a ordem de produção?'))return;const o=db.producoes.find(x=>x.id===id);if(o?.finishedApplied)reverseFinishedProduction(o);db.producoes=db.producoes.filter(x=>x.id!==id);saveDB();renderProducao(document.getElementById('module-root'));toast('Ordem excluída.','error')};
window.generateSale=id=>{const o=db.producoes.find(x=>x.id===id);setModule('vendas');setTimeout(()=>openSaleModal(null,o),0)};

function productsWithProduction(){const ids=new Set(db.producoes.map(o=>o.produtoId));return db.produtos.filter(p=>ids.has(p.id))}
function productColorOptions(p,selected){const ids=Array.isArray(p.corIds)?p.corIds:(p.corId?[p.corId]:[]);return productColors(p).map((name,i)=>{const id=ids[i];return `<option value="${id}" ${selected===id?'selected':''}>${esc(name)}</option>`}).join('')}
function renderVendas(root){root.innerHTML=`<div class="section-head"><div><h2>Vendas</h2><p>Registre pedidos e gere automaticamente o lançamento financeiro.</p></div><button class="btn btn-primary" id="add-sale">+ Nova venda</button></div><div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Cliente</th><th>Produto</th><th>Qtde</th><th>Cor</th><th>Valor unit.</th><th>Desconto</th><th>Valor final</th><th>Ações</th></tr></thead><tbody>${db.vendas.length?db.vendas.map(s=>`<tr><td>${dateBR(s.data)}</td><td>${esc(db.cadastros.clientes.find(c=>c.id===s.clienteId)?.nome||'-')}</td><td>${esc(db.produtos.find(p=>p.id===s.produtoId)?.descricao||'-')}</td><td>${num(s.qtde)}</td><td>${esc(db.cadastros.cores.find(c=>c.id===s.corId)?.descricao||'-')}</td><td>${money(s.valorUnit)}</td><td>${num(s.desconto).toFixed(2)}%</td><td><strong>${money(s.valorFinal)}</strong></td><td><div class="actions"><button class="small-btn" onclick="openSaleModal('${s.id}')">Editar</button><button class="small-btn" onclick="deleteSale('${s.id}')">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="9"><div class="empty-state">Nenhuma venda registrada.</div></td></tr>`}</tbody></table></div></div>`;document.getElementById('add-sale').onclick=()=>openSaleModal()}
function saleForm(r={},op){const productionProducts=r.orcamentoId?db.produtos:productsWithProduction();return `<div class="form-grid"><label class="col-6">Cliente *<select id="v_client" required><option value="">Selecione</option>${db.cadastros.clientes.map(x=>`<option value="${x.id}" ${r.clienteId===x.id?'selected':''}>${esc(x.nome)}</option>`).join('')}</select></label><label class="col-6">Produto *<select id="v_prod" required><option value="">Selecione</option>${productionProducts.map(x=>`<option value="${x.id}" ${(r.produtoId||op?.produtoId)===x.id?'selected':''}>${esc(x.descricao)}</option>`).join('')}</select></label><label class="col-3">Qtde *<input id="v_q" type="number" min="1" value="${r.qtde||op?.qtde||1}" required></label><label class="col-3">Cor *<select id="v_cor" required><option value="">Selecione</option>${((db.produtos.find(p=>p.id===(r.produtoId||op?.produtoId))?.corIds)||(db.produtos.find(p=>p.id===(r.produtoId||op?.produtoId))?.corId?[db.produtos.find(p=>p.id===(r.produtoId||op?.produtoId)).corId]:[])).map(id=>`<option value="${id}" ${(r.corId||op?.corId)===id?'selected':''}>${esc(db.cadastros.cores.find(c=>c.id===id)?.descricao||'-')}</option>`).join('')}</select></label><label class="col-3">Valor unitário (R$) *<input id="v_unit" inputmode="decimal" value="${moneyInput(r.valorUnit??(op?db.produtos.find(p=>p.id===op.produtoId)?.preco:''))}" required></label><label class="col-3">Desconto (%)<input id="v_disc" inputmode="decimal" value="${r.desconto??0}"></label><label class="col-12">Observações<textarea id="v_obs">${esc(r.observacoes||'')}</textarea></label><label class="col-12">Valor final calculado<input id="v_final" readonly value="${money(r.valorFinal||0)}"></label>${op?`<div class="col-12 inline-note">Ordem de produção vinculada: ${esc(op.codigo||productionCode(op))}</div>`:''}</div>`}
function syncFinancialForSale(obj,id){let f=db.financeiro.find(x=>x.vendaId===obj.id);if(!f){f={id:uid('FIN'),vendaId:obj.id,status:'Aberto'};db.financeiro.push(f)}f.data=obj.data;f.clienteId=obj.clienteId;f.produtoId=obj.produtoId;f.opId=obj.opId;f.qtde=obj.qtde;f.valor=obj.valorFinal}
function openSaleModal(id,op,draft){const r=id?db.vendas.find(x=>x.id===id)||{}:(draft||{});openModal('Vendas',id?'Editar venda':'Nova venda',saleForm(r,op),()=>{const client=document.getElementById('v_client').value,prod=document.getElementById('v_prod').value,cor=document.getElementById('v_cor').value,q=num(document.getElementById('v_q').value),unit=num(document.getElementById('v_unit').value),disc=num(document.getElementById('v_disc').value);if(!client||!prod||!cor||q<=0||unit<=0){toast('Preencha os campos obrigatórios.','error');return}const final=q*unit*(1-disc/100);const obj={id:r.id||uid('VEN'),data:r.data||nowISO(),clienteId:client,produtoId:prod,qtde:q,corId:cor,valorUnit:unit,desconto:disc,valorFinal:final,observacoes:document.getElementById('v_obs').value.trim(),opId:op?.id||r.opId||null,orcamentoId:r.orcamentoId||null};if(id)Object.assign(r,obj);else db.vendas.push(obj);syncFinancialForSale(obj,id);if(obj.opId){const order=db.producoes.find(o=>o.id===obj.opId);if(order)order.vendaId=obj.id}saveDB();closeModal();renderVendas(document.getElementById('module-root'));toast('Venda registrada e financeiro atualizado.')});setTimeout(()=>{const prodEl=document.getElementById('v_prod');prodEl?.addEventListener('change',()=>{const p=db.produtos.find(x=>x.id===prodEl.value);document.getElementById('v_cor').innerHTML='<option value="">Selecione</option>'+((p?.corIds)||(p?.corId?[p.corId]:[])).map(id=>`<option value="${id}">${esc(db.cadastros.cores.find(c=>c.id===id)?.descricao||'-')}</option>`).join('')});const u=()=>{const q=num(document.getElementById('v_q')?.value),unit=num(document.getElementById('v_unit')?.value),disc=num(document.getElementById('v_disc')?.value);if(document.getElementById('v_final'))document.getElementById('v_final').value=money(q*unit*(1-disc/100))};['v_q','v_unit','v_disc'].forEach(x=>document.getElementById(x)?.addEventListener('input',u));u()},0)}
window.openSaleModal=openSaleModal;window.deleteSale=id=>{if(!confirm('Excluir venda e lançamento financeiro vinculado?'))return;const v=db.vendas.find(x=>x.id===id);if(v?.opId){const o=db.producoes.find(x=>x.id===v.opId);if(o)o.vendaId=null}db.vendas=db.vendas.filter(x=>x.id!==id);db.financeiro=db.financeiro.filter(x=>x.vendaId!==id);saveDB();renderVendas(document.getElementById('module-root'));toast('Venda excluída.','error')};

function renderFinanceiro(root){root.innerHTML=`<div class="section-head"><div><h2>Financeiro</h2><p>Acompanhe os lançamentos gerados pelas vendas.</p></div></div><div class="filters"><label>Data<input type="date" id="f_date"></label><label>Cliente<select id="f_client"><option value="">Todos</option>${db.cadastros.clientes.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Produto<select id="f_prod"><option value="">Todos</option>${db.produtos.map(x=>`<option value="${x.id}">${esc(x.descricao)}</option>`).join('')}</select></label><label>Status<select id="f_status"><option value="">Todos</option><option>Aberto</option><option>Faturado</option></select></label></div><div class="cards financial-totals"><div class="card metric"><div class="label">Valor total</div><div class="value" id="fin-total">R$ 0,00</div></div><div class="card metric"><div class="label">Em aberto</div><div class="value" id="fin-open">R$ 0,00</div></div><div class="card metric"><div class="label">Faturado</div><div class="value" id="fin-billed">R$ 0,00</div></div></div><div class="card panel"><div id="fin-table"></div></div>`;['f_date','f_client','f_prod','f_status'].forEach(x=>document.getElementById(x).addEventListener('input',renderFinanceTable));renderFinanceTable()}
function renderFinanceTable(){const dt=document.getElementById('f_date').value,cl=document.getElementById('f_client').value,pr=document.getElementById('f_prod').value,st=document.getElementById('f_status').value;const rows=db.financeiro.filter(x=>(!dt||x.data.slice(0,10)===dt)&&(!cl||x.clienteId===cl)&&(!pr||x.produtoId===pr)&&(!st||x.status===st));const total=rows.reduce((s,x)=>s+num(x.valor),0),open=rows.filter(x=>x.status==='Aberto').reduce((s,x)=>s+num(x.valor),0),billed=rows.filter(x=>x.status==='Faturado').reduce((s,x)=>s+num(x.valor),0);document.getElementById('fin-total').textContent=money(total);document.getElementById('fin-open').textContent=money(open);document.getElementById('fin-billed').textContent=money(billed);document.getElementById('fin-table').innerHTML=rows.length?`<table class="data-table"><thead><tr><th>Data</th><th>Cliente</th><th>Produto</th><th>Ordem Produção</th><th>Qtde</th><th>Status</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(db.cadastros.clientes.find(c=>c.id===x.clienteId)?.nome||'-')}</td><td>${esc(db.produtos.find(p=>p.id===x.produtoId)?.descricao||'-')}</td><td>${esc(db.producoes.find(o=>o.id===x.opId)?.codigo||x.opId||'-')}</td><td>${num(x.qtde)}</td><td><span class="status-pill ${x.status==='Faturado'?'status-billed':'status-open'}">${x.status}</span></td><td><strong>${money(x.valor)}</strong></td><td><div class="actions"><button class="small-btn" onclick="exportFinancePdf('${x.id}')">Exportar PDF</button><button class="small-btn" onclick="changeFinStatus('${x.id}')">Alterar Status</button><button class="small-btn" onclick="deleteFinance('${x.id}')">Excluir</button></div></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Nenhum lançamento</strong>Não há registros com os filtros atuais.</div>`}
function exportFinancePdf(id){const f=db.financeiro.find(x=>x.id===id);const{jsPDF}=window.jspdf||{};if(!jsPDF){toast('Biblioteca de PDF indisponível.','error');return}const doc=new jsPDF();doc.setFontSize(18);doc.text('Navora 3D — Lançamento Financeiro',20,20);doc.setFontSize(11);const cliente=db.cadastros.clientes.find(c=>c.id===f.clienteId)?.nome||'-';const prod=db.produtos.find(p=>p.id===f.produtoId)?.descricao||'-';[['Data',dateBR(f.data)],['Cliente',cliente],['Produto',prod],['Ordem de Produção',db.producoes.find(o=>o.id===f.opId)?.codigo||f.opId||'-'],['Quantidade',String(f.qtde)],['Status',f.status],['Valor',money(f.valor)]].forEach((r,i)=>{doc.text(`${r[0]}: ${r[1]}`,20,42+i*10)});doc.save(`navora3d-financeiro-${f.id}.pdf`)}
window.exportFinancePdf=exportFinancePdf;window.changeFinStatus=id=>{const f=db.financeiro.find(x=>x.id===id);openModal('Alterar status','Lançamento financeiro',`<label>Status<select id="fin_status"><option ${f.status==='Aberto'?'selected':''}>Aberto</option><option ${f.status==='Faturado'?'selected':''}>Faturado</option></select></label>`,()=>{f.status=document.getElementById('fin_status').value;saveDB();closeModal();renderFinanceiro(document.getElementById('module-root'));toast('Status atualizado.')})};window.deleteFinance=id=>{if(!confirm('Excluir este lançamento financeiro?'))return;db.financeiro=db.financeiro.filter(x=>x.id!==id);saveDB();renderFinanceiro(document.getElementById('module-root'));toast('Lançamento excluído.','error')};

function quoteNextCode(){const nums=db.orcamentos.map(o=>parseInt(String(o.codigo||'').replace(/^ORC/i,''),10)).filter(Number.isFinite);return uidCode('ORC',Math.max(0,...nums)+1)}
function quoteTimeParts(value){const raw=String(value??'').replace('.',' ,').replace(/\s/g,'');const parts=String(value??'').replace(',','.').split('.');const h=parseInt(parts[0]||0,10)||0;const m=Math.max(0,Math.min(59,parseInt((parts[1]||'0').padEnd(2,'0').slice(0,2),10)||0));return{hours:h,minutes:m,totalHours:h+m/60}}
function quoteTimeText(value){const t=quoteTimeParts(value);return `${t.hours}h ${String(t.minutes).padStart(2,'0')}m`}
function quoteFilaments(r){return Array.isArray(r.filamentos)?r.filamentos:[]}
function filamentPurchases(){return db.compras.filter(c=>c.tipo==='Filamento')}
function itemPurchases(){return db.compras.filter(c=>c.tipo==='Componente'||c.tipo==='Outros')}
function purchaseUnitCost(c){return num(c.valor)/Math.max(0.0001,num(c.qtde))}
function calcQuote(r){
 const fil=quoteFilaments(r);
 const filamentCost=fil.reduce((sum,f)=>{const purchase=db.compras.find(x=>x.id===f.compraId);return sum+(num(f.gramas)*purchaseUnitCost(purchase||{}))},0);
 const printer=db.cadastros.impressoras.find(x=>x.id===r.impressoraId)||{};
 const time=quoteTimeParts(r.tempo);
 const energyRaw=num(printer.potencia)*time.totalHours*0.5;
 const kw=num(r.custoKwh??0.69);
 const energyFinal=energyRaw*kw/1000;
 const amort=num(printer.valor)/Math.max(0.0001,num(printer.vidaUtil))*time.totalHours;
 const items=(r.itens||[]).reduce((sum,i)=>sum+num(i.custoTotal),0);
 const fixedUnits=Math.max(1,Math.floor(num(r.fixedUnits)||1));
 const fixedCostTotal=Math.max(0,num(r.fixedCost)||0);
 const fixedUnitCost=fixedCostTotal/fixedUnits;
 const baseCost=filamentCost+energyFinal+items+fixedUnitCost+amort;
 const failureRate=num(r.falhas)/100;
 const failureCost=failureRate*(filamentCost+energyFinal+amort)*0.7;
 const totalCost=baseCost+failureCost;
 const units=Math.max(1,Math.floor(num(r.unidades)||1));
 const unitCost=totalCost/units;
 const markup=num(r.markup)||0;
 const consumer=unitCost*markup;
 const gross=consumer-unitCost;
 const tax=num(r.imposto)/100;
 const card=num(r.taxaCartao)/100;
 const ads=num(r.custoAnuncio)/100;
 const net=gross-(gross*tax)-(gross*card)-(gross*ads);
 const retailer=consumer/2;
 const rgross=retailer-unitCost;
 const rnet=rgross-(rgross*tax);
 return {filamentCost,energyRaw,energyFinal,amort,items,fixedCostTotal,fixedUnitCost,failureCost,totalCost,unitCost,consumer,gross,net,retailer,rgross,rnet,totalWeight:fil.reduce((sum,f)=>sum+num(f.gramas),0),printerCost:energyFinal+amort};
}
function quoteProductMatch(o){const name=String(o?.produto||'').trim().toLowerCase();return name?db.produtos.find(p=>String(p.descricao||'').trim().toLowerCase()===name)||null:null}
function quotePrimaryColorId(o,product){const purchaseColor=quoteFilaments(o).map(f=>db.compras.find(x=>x.id===f.compraId)?.corId).find(Boolean)||'';const productColorsIds=product?(Array.isArray(product.corIds)?product.corIds:(product.corId?[product.corId]:[])):[];if(purchaseColor&&productColorsIds.includes(purchaseColor))return purchaseColor;return productColorsIds[0]||''}
function quoteProductionMaterials(o){return quoteFilaments(o).map(f=>{const purchase=db.compras.find(x=>x.id===f.compraId);if(!purchase)return null;const stock=db.estoque.find(s=>String(s.descricao||'').toLowerCase()===String(purchase.descricao||'').toLowerCase()&&s.fornecedorId===purchase.fornecedorId&&s.tipo===purchase.tipo&&s.corId===purchase.corId&&s.materialId===purchase.materialId);return stock?{estoqueId:stock.id,descricao:stock.descricao,gramas:num(f.gramas),corId:stock.corId}:null}).filter(Boolean)}
function quoteToProductionDraft(o){const product=quoteProductMatch(o);return{produtoId:product?.id||'',corId:quotePrimaryColorId(o,product),qtde:Math.max(1,Math.floor(num(o.unidades)||1)),materiais:quoteProductionMaterials(o),status:'Aguardando',observacoes:'',finishedApplied:false,vendaId:null,orcamentoId:o.id}}
function quoteToSaleDraft(o){const product=quoteProductMatch(o),calc=calcQuote(o),qty=Math.max(1,Math.floor(num(o.unidades)||1));return{clienteId:o.clienteId||'',produtoId:product?.id||'',qtde:qty,corId:quotePrimaryColorId(o,product),valorUnit:calc.consumer,desconto:0,valorFinal:calc.consumer*qty,observacoes:'',opId:null,orcamentoId:o.id}}
function generateProductionFromQuote(id){const o=db.orcamentos.find(x=>x.id===id);if(!o)return;const draft=quoteToProductionDraft(o);setModule('producao');setTimeout(()=>openOPModal(null,draft),0)}
function generateSaleFromQuote(id){const o=db.orcamentos.find(x=>x.id===id);if(!o)return;const draft=quoteToSaleDraft(o);setModule('vendas');setTimeout(()=>openSaleModal(null,null,draft),0)}
window.generateProductionFromQuote=generateProductionFromQuote;window.generateSaleFromQuote=generateSaleFromQuote;
function renderOrcamentos(root){
 const f=window.quoteFilters||{codigo:'',data:'',produto:'',cliente:''};
 const rows=db.orcamentos.filter(o=>(!f.codigo||String(o.codigo||'').toLowerCase().includes(f.codigo.toLowerCase()))&&(!f.data||(o.data||'').slice(0,10)===f.data)&&(!f.produto||String(o.produto||'').toLowerCase().includes(f.produto.toLowerCase()))&&(!f.cliente||o.clienteId===f.cliente));
 root.innerHTML=`<div class="section-head"><div><h2>Orçamentos</h2><p>Crie propostas profissionais e acompanhe os orçamentos enviados aos clientes.</p></div><button class="btn btn-primary" id="add-quote">+ Novo orçamento</button></div>
 <div class="filters"><label>Código<input id="qf_code" value="${esc(f.codigo)}"></label><label>Data<input id="qf_date" type="date" value="${esc(f.data)}"></label><label>Produto<input id="qf_product" value="${esc(f.produto)}"></label><label>Cliente<select id="qf_client"><option value="">Todos</option>${db.cadastros.clientes.map(c=>`<option value="${c.id}" ${f.cliente===c.id?'selected':''}>${esc(c.nome)}</option>`).join('')}</select></label></div>
 <div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Data</th><th>Cliente</th><th>Produto</th><th>Peso</th><th>Preço consumidor</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(o=>{const c=calcQuote(o);const client=db.cadastros.clientes.find(x=>x.id===o.clienteId)?.nome||o.clienteNome||'-';return `<tr><td><strong>${esc(o.codigo)}</strong></td><td>${dateBR(o.data)}</td><td>${esc(client)}</td><td>${esc(o.produto)}</td><td>${c.totalWeight.toFixed(2)} g</td><td><strong>${money(c.consumer)}</strong></td><td><div class="actions"><button class="small-btn" onclick="openQuoteModal('${o.id}')">Editar</button><button class="small-btn" onclick="generateProductionFromQuote('${o.id}')">Gerar produção</button><button class="small-btn" onclick="generateSaleFromQuote('${o.id}')">Gerar venda</button><button class="small-btn" onclick="deleteQuote('${o.id}')">Excluir</button><button class="small-btn" onclick="previewQuote('${o.id}')">Imprimir</button></div></td></tr>`}).join(''):`<tr><td colspan="7"><div class="empty-state"><strong>Nenhum orçamento</strong>Crie o primeiro orçamento para começar.</div></td></tr>`}</tbody></table></div></div>`;
 document.getElementById('add-quote').onclick=()=>openQuoteModal();
 ['qf_code','qf_date','qf_product','qf_client'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{window.quoteFilters={codigo:document.getElementById('qf_code').value,data:document.getElementById('qf_date').value,produto:document.getElementById('qf_product').value,cliente:document.getElementById('qf_client').value};renderOrcamentos(document.getElementById('module-root'))}));
}
function quoteForm(r={}){
 const selectedImp=r.impressoraId||'';
 return `<div class="quote-form-layout"><div class="form-grid">
 <label class="col-6">Cliente cadastrado<select id="q_client"><option value="">Selecione</option>${db.cadastros.clientes.map(c=>`<option value="${c.id}" ${r.clienteId===c.id?'selected':''}>${esc(c.nome)}</option>`).join('')}</select><small class="muted">Use um cliente cadastrado ou informe o nome ao lado.</small></label>
 <label class="col-6">Nome do cliente<input id="q_client_name" value="${esc(r.clienteNome||'')}" placeholder="Digite o nome do cliente"></label>
 <label class="col-3">Data<input id="q_date" type="date" value="${r.data?r.data.slice(0,10):new Date().toISOString().slice(0,10)}"></label>
 <label class="col-3">Código<input value="${esc(r.codigo||'(gerado ao salvar)')}" disabled></label>
 <label class="col-9">Produto *<input id="q_prod" value="${esc(r.produto||'')}" placeholder="Digite o produto do orçamento" required></label>
 <label class="col-3">Tempo *<input id="q_time" inputmode="decimal" placeholder="1,32" value="${esc(r.tempo||'')}" required><small class="muted">Ex.: 1,32 = 1h32</small></label>
 <div class="col-12 inline-note">Informe <strong>Cliente cadastrado</strong> ou <strong>Nome do cliente</strong>. Apenas um dos dois deve ser preenchido.</div>
 <div class="col-12 box-section quote-filaments-box"><div class="box-section-title">MATÉRIA PRIMA / FILAMENTOS</div><div class="quote-sheet-head"><span>Filamento</span><span>Custo/kg</span><span>Gramas</span><span>Custo</span><span></span></div><div id="quote-filaments">${quoteFilamentRows(r)}</div><button type="button" class="btn btn-secondary" id="q-add-filament">+ Adicionar filamento</button><div class="quote-total-row"><span>Peso total</span><strong id="q-total-weight">0,00 g</strong></div><div class="quote-total-row"><span>Custo dos filamentos</span><strong id="q-filament-cost">R$ 0,00</strong></div></div>
 <div class="col-12 box-section printer-box"><div class="box-section-title">IMPRESSORA</div><div class="form-grid"><label class="col-5">Impressora *<select id="q_printer" required><option value="">Selecione</option>${db.cadastros.impressoras.map(i=>`<option value="${i.id}" ${selectedImp===i.id?'selected':''}>${esc(i.nome)} • ${esc(i.modelo||i.marca||'')}</option>`).join('')}</select></label><label class="col-3">Potência (W)<input id="q_power" readonly value="0"></label><label class="col-4">Custo Kw/h<input id="q_kw" inputmode="decimal" value="${moneyInput(r.custoKwh??0.69)}"></label><div class="col-12 inline-note">Energia = Potência × Tempo × 0,5. Energia final = Energia × Custo Kw/h ÷ 1000. Amortização = Valor da impressora ÷ Vida útil × Tempo.</div></div></div>
 <div class="col-12"><div class="section-head compact"><div><h3 style="margin:0">Acessórios e embalagens</h3><p style="margin:4px 0 0">Itens cadastrados em Compras como componentes ou outros.</p></div><button type="button" class="btn btn-secondary" id="q-add-item">+ Adicionar item</button></div><div class="card panel compact-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Qtde</th><th>Custo unitário</th><th>Custo total</th><th></th></tr></thead><tbody id="q-items-body">${quoteItemRows(r)}</tbody></table></div><div class="quote-total-row"><span>Total dos itens</span><strong id="q-items-total">R$ 0,00</strong></div></div></div>
 <div class="col-12 box-section fixed-box"><div class="box-section-title">CUSTO FIXO</div><div class="form-grid"><label class="col-6">Custo fixo (R$)<input id="q_fixed_cost" inputmode="decimal" value="${moneyInput(r.fixedCost??0)}"></label><label class="col-6">Unidades / mês<input id="q_fixed_units" type="number" min="1" step="1" value="${r.fixedUnits??1}"></label></div></div>
 <div class="col-12 box-section costs-box"><div class="box-section-title">CUSTOS</div><div class="form-grid"><label class="col-3">% Falhas<input id="q_fail" inputmode="decimal" value="${r.falhas??0}"></label><label class="col-3">Unidades<input id="q_units" type="number" min="1" step="1" value="${r.unidades||1}"></label><label class="col-3">Custo total<input id="q_total_cost" readonly value="R$ 0,00"></label><label class="col-3">Custo unitário<input id="q_unit_cost" readonly value="R$ 0,00"></label></div><div class="inline-note">Custo total = filamento + energia + acessórios/embalagens + custo fixo por unidade + amortização + falhas. Falhas aplicadas sobre filamento + energia + amortização × 0,7.</div></div>
 <div class="col-12 box-section other-box"><div class="box-section-title">OUTROS</div><div class="form-grid"><label class="col-3">Markup<input id="q_markup" type="number" step="1" value="${r.markup??1}"></label><label class="col-3">Imposto (%)<input id="q_tax" inputmode="decimal" value="${r.imposto??0}"></label><label class="col-3">Taxa cartão (%)<input id="q_card" inputmode="decimal" value="${r.taxaCartao??0}"></label><label class="col-3">Custo anúncio (%)<input id="q_ads" inputmode="decimal" value="${r.custoAnuncio??0}"></label></div></div>
 <div class="col-12 box-section pricing-box"><div class="box-section-title">PRECIFICAÇÃO</div><div class="pricing-grid"><div><span>Preço consumidor final</span><strong id="q_consumer">R$ 0,00</strong></div><div><span>Lucro bruto</span><strong id="q_gross">R$ 0,00</strong></div><div><span>Lucro líquido</span><strong id="q_net">R$ 0,00</strong></div><div><span>Preço lojista</span><strong id="q_retailer">R$ 0,00</strong></div><div><span>Lucro bruto lojista</span><strong id="q_rgross">R$ 0,00</strong></div><div><span>Lucro líquido lojista</span><strong id="q_rnet">R$ 0,00</strong></div></div></div>
 </div></div>`
}
function quoteFilamentRows(r){
 const rows=quoteFilaments(r);
 if(!rows.length)return `<div class="inline-note quote-empty-filament">Nenhum filamento adicionado.</div>`;
 return rows.map((f,i)=>{const c=db.compras.find(x=>x.id===f.compraId)||{};const unitKg=numberPerKg(c);return `<div class="quote-line" data-index="${i}"><label class="quote-main">Filamento<select class="q-fil" data-index="${i}"><option value="">Selecione</option>${filamentPurchases().map(x=>`<option value="${x.id}" ${x.id===f.compraId?'selected':''}>${esc(x.descricao)} • ${esc(db.cadastros.cores.find(co=>co.id===x.corId)?.descricao||'-')}</option>`).join('')}</select></label><div class="quote-readonly-value">${money(unitKg)}/kg</div><label>Gramas<input class="q-fil-g" data-index="${i}" inputmode="decimal" value="${f.gramas??''}"></label><div class="quote-filament-cost"><strong class="q-fil-cost-display" data-index="${i}">${money(num(f.gramas)*purchaseUnitCost(c))}</strong></div><button type="button" class="small-btn btn-danger q-remove-fil" data-index="${i}">Remover</button></div>`}).join('')
}
function numberPerKg(c){return num(c.qtde)>0?purchaseUnitCost(c)*1000:0}
function quoteItemRows(r){const rows=r.itens||[];if(!rows.length)return `<tr><td colspan="5" class="muted">Nenhum item adicional.</td></tr>`;return rows.map((it,i)=>`<tr data-index="${i}"><td>${esc(it.nome||db.compras.find(c=>c.id===it.compraId)?.descricao||'-')}</td><td>${num(it.qtde).toFixed(2)}</td><td>${money(it.custoUnitario)}</td><td><strong>${money(it.custoTotal)}</strong></td><td><button type="button" class="small-btn btn-danger q-remove-item" data-index="${i}">Excluir</button></td></tr>`).join('')}
function collectQuoteDraft(r={}){return{id:r.id||uid('ORC'),codigo:r.codigo||quoteNextCode(),data:document.getElementById('q_date').value?new Date(document.getElementById('q_date').value+'T12:00:00').toISOString():nowISO(),clienteId:document.getElementById('q_client').value,clienteNome:document.getElementById('q_client_name')?.value.trim()||'',produto:document.getElementById('q_prod').value.trim(),tempo:document.getElementById('q_time').value.trim(),filamentos:[...document.querySelectorAll('.quote-line')].map(row=>({compraId:row.querySelector('.q-fil').value,gramas:num(row.querySelector('.q-fil-g').value)})).filter(x=>x.compraId&&x.gramas>0),impressoraId:document.getElementById('q_printer').value,custoKwh:num(document.getElementById('q_kw').value),falhas:num(document.getElementById('q_fail').value),unidades:Math.max(1,Math.floor(num(document.getElementById('q_units').value)||1)),fixedCost:num(document.getElementById('q_fixed_cost').value),fixedUnits:Math.max(1,Math.floor(num(document.getElementById('q_fixed_units').value)||1)),markup:num(document.getElementById('q_markup').value),imposto:num(document.getElementById('q_tax').value),taxaCartao:num(document.getElementById('q_card').value),custoAnuncio:num(document.getElementById('q_ads').value),itens:r.itens||[]}}
function updateQuotePreview(){
 const printer=db.cadastros.impressoras.find(x=>x.id===document.getElementById('q_printer')?.value);
 const power=document.getElementById('q_power'); if(power)power.value=printer?.potencia??0;
 const draft=collectQuoteDraft({itens:window.quoteDraftItems||[]});
 const c=calcQuote(draft);
 const setText=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v};
 const setValue=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v};
 setText('q-total-weight',`${c.totalWeight.toFixed(2).replace('.',',')} g`);setText('q-filament-cost',money(c.filamentCost));setText('q-items-total',money(c.items));setValue('q_total_cost',money(c.totalCost));setValue('q_unit_cost',money(c.unitCost));setText('q_consumer',money(c.consumer));setText('q_gross',money(c.gross));setText('q_net',money(c.net));setText('q_retailer',money(c.retailer));setText('q_rgross',money(c.rgross));setText('q_rnet',money(c.rnet));
 document.querySelectorAll('.q-fil-cost-display').forEach(el=>{const row=el.closest('.quote-line');const f=db.compras.find(x=>x.id===row?.querySelector('.q-fil')?.value);el.textContent=money(num(row?.querySelector('.q-fil-g')?.value)*purchaseUnitCost(f||{}))});
}
function openQuoteItemModal(){
 window.quoteTransient=collectQuoteDraft({itens:window.quoteDraftItems||[]});
 const options=itemPurchases().map(x=>`<option value="${x.id}">${esc(x.descricao)} • ${esc(x.tipo)}</option>`).join('');
 openModal('Adicionar item','Componentes e outros',`<div class="form-grid"><label class="col-6">Item *<select id="qi_item" required><option value="">Selecione</option>${options}</select></label><label class="col-3">Qtde *<input id="qi_qty" inputmode="decimal" value="1" required></label><label class="col-3">Custo unitário (R$) *<input id="qi_unit" inputmode="decimal" value="0,00" required></label><label class="col-12">Custo total<input id="qi_total" readonly value="R$ 0,00"></label></div>`,()=>{const id=document.getElementById('qi_item').value,q=num(document.getElementById('qi_qty').value),unit=num(document.getElementById('qi_unit').value);if(!id||q<=0){toast('Selecione o item e informe a quantidade.','error');return}window.quoteDraftItems=window.quoteDraftItems||[];const c=db.compras.find(x=>x.id===id);window.quoteDraftItems.push({compraId:id,nome:c?.descricao||'',qtde:q,custoUnitario:unit,custoTotal:q*unit});const draft={...window.quoteTransient,itens:window.quoteDraftItems};closeModal();openQuoteModalDraft(draft)});
 setTimeout(()=>{const update=()=>{const el=document.getElementById('qi_total');if(el)el.value=money(num(document.getElementById('qi_qty').value)*num(document.getElementById('qi_unit').value))};document.getElementById('qi_qty').addEventListener('input',update);document.getElementById('qi_unit').addEventListener('input',update);document.getElementById('qi_item').addEventListener('change',()=>{const c=db.compras.find(x=>x.id===document.getElementById('qi_item').value);if(c)document.getElementById('qi_unit').value=moneyInput(purchaseUnitCost(c));update()});update()},0)
}
function refreshQuoteItemGrid(){const body=document.getElementById('q-items-body');const rows=window.quoteDraftItems||[];if(!body)return;body.innerHTML=quoteItemRows({itens:rows});document.querySelectorAll('.q-remove-item').forEach(btn=>btn.addEventListener('click',()=>{window.quoteDraftItems.splice(Number(btn.dataset.index),1);refreshQuoteItemGrid();updateQuotePreview()}));updateQuotePreview()}
function bindQuoteForm(){
 ['q_time','q_printer','q_kw','q_fixed_cost','q_fixed_units','q_fail','q_units','q_markup','q_tax','q_card','q_ads'].forEach(id=>document.getElementById(id)?.addEventListener('input',updateQuotePreview));
 document.getElementById('q_printer')?.addEventListener('change',updateQuotePreview);
 const clientSel=document.getElementById('q_client'),clientName=document.getElementById('q_client_name');
 clientSel?.addEventListener('change',()=>{if(clientSel.value&&clientName)clientName.value='';updateQuotePreview()});
 clientName?.addEventListener('input',()=>{if(clientName.value.trim()&&clientSel)clientSel.value='';updateQuotePreview()});
 document.getElementById('q-add-item')?.addEventListener('click',openQuoteItemModal);
 document.getElementById('q-add-filament')?.addEventListener('click',()=>{const box=document.getElementById('quote-filaments');const current=[...document.querySelectorAll('.quote-line')].map(row=>({compraId:row.querySelector('.q-fil').value,gramas:num(row.querySelector('.q-fil-g').value)}));current.push({compraId:'',gramas:0});box.innerHTML=quoteFilamentRows({filamentos:current});bindQuoteFilamentRows();updateQuotePreview()});
 bindQuoteFilamentRows();refreshQuoteItemGrid();updateQuotePreview()
}
function bindQuoteFilamentRows(){document.querySelectorAll('.q-fil,.q-fil-g').forEach(el=>{el.addEventListener('input',updateQuotePreview);el.addEventListener('change',()=>{const row=el.closest('.quote-line');if(el.classList.contains('q-fil')){const f=db.compras.find(x=>x.id===el.value);const ro=row?.querySelector('.quote-readonly-value');if(ro)ro.textContent=`${money(numberPerKg(f||{}))}/kg`}updateQuotePreview()})});document.querySelectorAll('.q-remove-fil').forEach(btn=>btn.addEventListener('click',()=>{const current=[...document.querySelectorAll('.quote-line')].map(row=>({compraId:row.querySelector('.q-fil').value,gramas:num(row.querySelector('.q-fil-g').value)}));current.splice(Number(btn.dataset.index),1);document.getElementById('quote-filaments').innerHTML=quoteFilamentRows({filamentos:current});bindQuoteFilamentRows();updateQuotePreview()}))}
function validateQuoteCustomer(){const client=document.getElementById('q_client').value,clientName=document.getElementById('q_client_name').value.trim();return (client&&!clientName)||(!client&&clientName)}
function saveQuoteFromModal(r,id){const prod=document.getElementById('q_prod').value.trim(),time=document.getElementById('q_time').value.trim(),printer=document.getElementById('q_printer').value,fil=[...document.querySelectorAll('.quote-line')].map(row=>({compraId:row.querySelector('.q-fil').value,gramas:num(row.querySelector('.q-fil-g').value)})).filter(x=>x.compraId&&x.gramas>0);if(!validateQuoteCustomer()){toast('Informe cliente cadastrado ou nome do cliente, mas não os dois.','error');return false}if(!prod||!time||!printer||!fil.length){toast('Preencha produto, tempo, impressora e ao menos um filamento.','error');return false}const obj=collectQuoteDraft(r);obj.itens=window.quoteDraftItems||[];obj.filamentos=fil;obj.clienteId=document.getElementById('q_client').value;obj.clienteNome=document.getElementById('q_client_name').value.trim();if(id)Object.assign(r,obj);else db.orcamentos.push(obj);saveDB();closeModal();renderOrcamentos(document.getElementById('module-root'));toast('Orçamento salvo.');return true}
function openQuoteModalDraft(draft){window.quoteDraftItems=JSON.parse(JSON.stringify(draft.itens||[]));openModal('Orçamento','Novo orçamento',quoteForm(draft),()=>saveQuoteFromModal(draft,false));setTimeout(bindQuoteForm,0)}
function openQuoteModal(id){const r=id?db.orcamentos.find(x=>x.id===id)||{}:{};window.quoteDraftItems=JSON.parse(JSON.stringify(r.itens||[]));openModal('Orçamento',id?'Editar orçamento':'Novo orçamento',quoteForm(r),()=>saveQuoteFromModal(r,id));setTimeout(bindQuoteForm,0)}
window.openQuoteModal=openQuoteModal;window.deleteQuote=id=>{if(!confirm('Excluir este orçamento?'))return;db.orcamentos=db.orcamentos.filter(x=>x.id!==id);saveDB();renderOrcamentos(document.getElementById('module-root'));toast('Orçamento excluído.','error')};
function quotePrintHTML(o){const client=db.cadastros.clientes.find(c=>c.id===o.clienteId)||{};const clientName=client.nome||o.clienteNome||'-';const printer=db.cadastros.impressoras.find(i=>i.id===o.impressoraId)||{};const c=calcQuote(o);const fil=o.filamentos.map(f=>{const p=db.compras.find(x=>x.id===f.compraId);return `<tr><td>${esc(p?.descricao||'-')}</td><td>${esc(db.cadastros.cores.find(co=>co.id===p?.corId)?.descricao||'-')}</td><td>${num(f.gramas).toFixed(2)} g</td><td>${money(num(f.gramas)*purchaseUnitCost(p||{}))}</td></tr>`}).join('');const items=(o.itens||[]).map(i=>`<tr><td>${esc(i.nome||db.compras.find(x=>x.id===i.compraId)?.descricao||'-')}</td><td>${num(i.qtde).toFixed(2)}</td><td>${money(i.custoUnitario)}</td><td>${money(i.custoTotal)}</td></tr>`).join('');return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(o.codigo)}</title><style>body{font-family:Arial,sans-serif;color:#182230;padding:36px;background:#fff}.sheet{max-width:900px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #275dff;padding-bottom:18px}.logo{display:flex;gap:12px;align-items:center}.mark{width:56px;height:56px;border-radius:16px;background:#275dff;color:#fff;display:grid;place-items:center;font-weight:800}.brand{font-size:26px;font-weight:800}.brand span{color:#275dff}.sub{color:#6b778c;font-size:12px}.quote-code{font-size:20px;font-weight:800;text-align:right}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.box{border:1px solid #e6ebf2;border-radius:12px;padding:14px}.title{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#6b778c;font-weight:700;margin-bottom:8px}.box strong{font-size:14px}.section{margin-top:18px}.section h2{font-size:14px;margin:0 0 8px}.table{width:100%;border-collapse:collapse;font-size:12px}.table th{background:#f5f7fb;text-align:left;padding:9px}.table td{padding:9px;border-bottom:1px solid #edf0f5}.totals{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.total{border-radius:12px;padding:13px;background:#f8fafc}.total span{display:block;font-size:10px;color:#6b778c;text-transform:uppercase}.total strong{display:block;margin-top:6px;font-size:16px}.highlight{background:#eef3ff}.footer{margin-top:26px;padding-top:14px;border-top:1px solid #e6ebf2;color:#6b778c;font-size:10px}@media print{body{padding:0}.sheet{max-width:none}}</style></head><body><div class="sheet"><div class="head"><div class="logo"><div class="mark">N3D</div><div><div class="brand">Navora <span>3D</span></div><div class="sub">Sua ideia em três dimensões</div></div></div><div><div class="quote-code">${esc(o.codigo)}</div><div class="sub">Data: ${dateBR(o.data)}</div></div></div><div class="grid"><div class="box"><div class="title">Cliente</div><strong>${esc(clientName)}</strong><div class="sub">${esc(client.cpf||'')} ${client.telefone?'• '+esc(client.telefone):''}</div><div class="sub">${esc(client.email||'')}</div><div class="sub">${esc(client.cidade||'')}</div></div><div class="box"><div class="title">Produto</div><strong>${esc(o.produto)}</strong><div class="sub">Tempo de produção: ${quoteTimeText(o.tempo)}</div><div class="sub">Unidades: ${num(o.unidades)}</div></div></div><div class="section"><h2>Matéria prima / filamentos</h2><table class="table"><thead><tr><th>Filamento</th><th>Cor</th><th>Gramas</th><th>Custo</th></tr></thead><tbody>${fil||'<tr><td colspan="4">-</td></tr>'}</tbody></table></div><div class="section"><h2>Impressora</h2><table class="table"><tbody><tr><td>Nome / Modelo</td><td>${esc(printer.nome||'-')} ${printer.modelo?'• '+esc(printer.modelo):''}</td><td>Potência</td><td>${num(printer.potencia).toFixed(2)} W</td></tr><tr><td>Tempo</td><td>${quoteTimeText(o.tempo)}</td><td>Custo Kw/h</td><td>${money(o.custoKwh??0.69)}</td></tr></tbody></table></div><div class="section"><h2>Acessórios e embalagens</h2><table class="table"><thead><tr><th>Item</th><th>Qtde</th><th>Unitário</th><th>Total</th></tr></thead><tbody>${items||'<tr><td colspan="4">Nenhum item adicional.</td></tr>'}</tbody></table></div><div class="section"><div class="totals"><div class="total"><span>Custo total</span><strong>${money(c.totalCost)}</strong></div><div class="total"><span>Custo unitário</span><strong>${money(c.unitCost)}</strong></div><div class="total highlight"><span>Preço consumidor final</span><strong>${money(c.consumer)}</strong></div></div><div class="totals"><div class="total"><span>Lucro bruto</span><strong>${money(c.gross)}</strong></div><div class="total"><span>Lucro líquido</span><strong>${money(c.net)}</strong></div><div class="total"><span>Preço lojista</span><strong>${money(c.retailer)}</strong></div></div><div class="totals"><div class="total"><span>Lucro bruto lojista</span><strong>${money(c.rgross)}</strong></div><div class="total"><span>Lucro líquido lojista</span><strong>${money(c.rnet)}</strong></div><div class="total"><span>Falhas</span><strong>${money(c.failureCost)}</strong></div></div></div><div class="footer">Orçamento gerado pela Navora 3D. Valores sujeitos às condições comerciais acordadas com o cliente.</div></div></body></html>`}
function previewQuote(id){const o=db.orcamentos.find(x=>x.id===id);if(!o)return;const html=quotePrintHTML(o);openModal('Visualização do orçamento',o.codigo,`<div class="quote-preview-wrap"><iframe id="quote-preview-frame" title="Pré-visualização do orçamento" style="width:100%;height:70vh;border:1px solid var(--line);border-radius:12px"></iframe></div>`,null);setTimeout(()=>{const frame=document.getElementById('quote-preview-frame');frame.srcdoc=html;frame.addEventListener('load',()=>{const head=frame.contentDocument.createElement('div');head.innerHTML='<button style="position:fixed;top:10px;right:10px;padding:10px 14px;background:#275dff;color:#fff;border:0;border-radius:8px;font-weight:700;cursor:pointer">Imprimir</button>';frame.contentDocument.body.prepend(head);head.firstElementChild.onclick=()=>frame.contentWindow.print()})},0)}
window.previewQuote=previewQuote;

function renderConfiguracoes(root){root.innerHTML=`<div class="section-head"><div><h2>Configurações</h2><p>Backup, restauração e administração local da base.</p></div></div><div class="grid-2"><div class="card panel"><h3>Backup</h3><p class="muted">Exporte todos os dados da Navora 3D em JSON.</p><button class="btn btn-primary" id="export-json">Exportar backup JSON</button></div><div class="card panel"><h3>Restauração</h3><p class="muted">Importe um backup JSON completo para recuperar sua base.</p><input id="import-json" type="file" accept="application/json,.json"><div style="height:8px"></div><button class="btn btn-secondary" id="import-btn">Importar e restaurar</button></div><div class="card panel"><h3>Base local</h3><p class="muted">Todos os dados estão salvos localmente no navegador deste dispositivo.</p><div class="inline-note">Última atualização: ${dateBR(db.meta.updatedAt)} ${new Date(db.meta.updatedAt).toLocaleTimeString('pt-BR')}</div></div><div class="card panel"><h3>Dados demo</h3><p class="muted">Pode carregar uma base inicial para testar o fluxo completo.</p><button class="btn btn-danger" id="clear-db">Limpar toda a base</button></div></div>`;document.getElementById('export-json').onclick=exportBackup;document.getElementById('import-btn').onclick=importBackup;document.getElementById('clear-db').onclick=()=>{if(!confirm('Esta ação apagará todos os dados locais.'))return;db=blankDB();saveDB();toast('Base limpa.','error');renderConfiguracoes(root)}}
function exportBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`navora3d-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exportado.')}
function importBackup(){const file=document.getElementById('import-json').files[0];if(!file){toast('Selecione um arquivo JSON.','error');return}const fr=new FileReader();fr.onload=()=>{try{const data=JSON.parse(fr.result);if(!data.cadastros||!data.produtos)throw new Error('Formato inválido');db=normalizeDB(data);saveDB();toast('Backup restaurado com sucesso.');renderConfiguracoes(document.getElementById('module-root'))}catch{toast('Arquivo inválido ou corrompido.','error')}};fr.readAsText(file)}

function openModal(title,subtitle,body,onSave){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><h3>${esc(title)}</h3><div class="muted" style="font-size:12px;margin-top:3px">${esc(subtitle||'')}</div></div><button class="icon-btn" id="modal-close">×</button></div><div class="modal-body">${body||''}</div>${onSave?`<div class="modal-foot"><button class="btn btn-secondary" id="modal-cancel">Cancelar</button><button class="btn btn-primary" id="modal-save">Salvar</button></div>`:''}</div></div>`;document.getElementById('modal-close').onclick=closeModal;document.getElementById('modal-cancel')?.addEventListener('click',closeModal);document.getElementById('modal-save')?.addEventListener('click',onSave);document.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()})}
function closeModal(){document.getElementById('modal-root').innerHTML=''}

document.addEventListener('DOMContentLoaded',()=>{
 document.getElementById('today-label').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});
 document.getElementById('login-form').addEventListener('submit',e=>{e.preventDefault();if(document.getElementById('login-user').value===LOGIN.user&&document.getElementById('login-pass').value===LOGIN.pass){sessionStorage.setItem('navora3d_auth','1');document.getElementById('login-screen').classList.add('hidden');document.getElementById('app-shell').classList.remove('hidden');setModule('dashboard')}else toast('Usuário ou senha inválidos.','error')});
 document.querySelectorAll('.nav-item[data-module]').forEach(b=>b.addEventListener('click',()=>{setModule(b.dataset.module);document.querySelector('.sidebar').classList.remove('open')}));
 document.getElementById('logout-btn').addEventListener('click',()=>{sessionStorage.removeItem('navora3d_auth');document.getElementById('app-shell').classList.add('hidden');document.getElementById('login-screen').classList.remove('hidden')});
 document.getElementById('mobile-menu').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
 if(sessionStorage.getItem('navora3d_auth')==='1'){document.getElementById('login-screen').classList.add('hidden');document.getElementById('app-shell').classList.remove('hidden');setModule('dashboard')}
});
